import React from 'react';

const WelcomeBanner = () => {
  return (
    <div className="mb-6 sm:mb-8 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 p-4 sm:p-6 text-white shadow-lg">
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold mb-1 sm:mb-2">Bon retour, Enzo ! 👋</h1>
          <p className="text-sm sm:text-base opacity-90">Voici ce qui se passe dans votre boutique aujourd'hui.</p>
        </div>
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
          <div className="px-3 sm:px-4 py-2 bg-white/20 rounded-xl backdrop-blur-sm order-2 sm:order-1">
            <span className="text-xs sm:text-sm line-clamp-2 sm:line-clamp-1">Dernière connexion : Aujourd'hui à 09:42</span>
          </div>
          <button className="px-3 sm:px-4 py-2 bg-white text-primary-600 font-medium rounded-xl hover:bg-white/90 transition-colors text-sm sm:text-base order-1 sm:order-2">
            Voir rapport
          </button>
        </div>
      </div>
    </div>
  );
};

export default WelcomeBanner;
